input.command:
cd /shared; python3 -c "
import csv
from collections import defaultdict
from decimal import Decimal
o=list(csv.DictReader(open('/shared/orders.csv')))
c={r['order_id']:r for r in csv.DictReader(open('/home/agent/private/customers.csv'))}
ids=[r['order_id'] for r in o]
print('dup orders',len(ids)-len(set(ids)),'missing in cust',sum(1 for i in ids if i not in c),'bad amounts',[r['amount'] for r in o if not r['amount'].replace('.','',1).replace('-','',1).isdigit()][:5])
t=defaultdict(Decimal)
for r in o:
    if r['order_id'] in c: t[c[r['order_id']]['region']]+=Decimal(r['amount'])
res={k:str(v.quantize(Decimal('0.01'))) for k,v in sorted(t.items())}
import json; s=json.dumps(res); print(s)
open('/shared/result_B.json','w').write(s)
"

